 static readonly Color[] DefaultColors={Color.FromArgb(115,87,255),Color.FromArgb(0,120,212),Color.FromArgb(224,68,81),Color.FromArgb(19,150,110),Color.FromArgb(244,171,44),Color.FromArgb(38,43,56)};
 void InitializeEditingTools(){
  var card=new StudioCard();sidebar.Controls.Add(card);sidebar.Controls.SetChildIndex(card,1);var paletteToggle=ModernButton(card,"Palette de couleurs ▾","",delegate{},220,false);paletteToggle.Font=new Font("Segoe UI",10,FontStyle.Bold);
