  var reference=ModernButton(card,"Choisir une image…","",delegate{using(var d=new OpenFileDialog(){Filter="Images|*.png;*.jpg;*.jpeg;*.bmp"})if(d.ShowDialog()==DialogResult.OK){using(var b=new Bitmap(d.FileName))preferences.ReferenceColors=ExtractPalette(b).Select(c=>c.ToArgb()).ToArray();paletteSource.SelectedIndex=2;UpdateAdaptivePalette();SavePreferences();}},220,false);
  paletteReference=reference;paletteSource.SelectedIndexChanged+=delegate{UpdateAdaptivePalette();RefreshPaletteControls();SavePreferences();};tips.SetToolTip(reference,"Utiliser les couleurs d’un logo, d’une charte ou d’une autre image, sans importer cette image dans le projet.");
  paletteSource.Visible=paletteInfo.Visible=reference.Visible=false;paletteToggle.Click+=delegate{paletteExpanded=!paletteExpanded;paletteSource.Visible=paletteInfo.Visible=paletteExpanded;RefreshPaletteControls();paletteToggle.Text=paletteExpanded?"Palette de couleurs ▴":"Palette de couleurs ▾";};
  inlineText=new TextBox(){Multiline=true,AcceptsReturn=true,BorderStyle=BorderStyle.FixedSingle,Visible=false,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};canvas.Controls.Add(inlineText);inlineText.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Escape){FinishInlineText(false);e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Enter){FinishInlineText(true);e.SuppressKeyPress=true;}};
