 public static Color[] ExtractPalette(Bitmap image){
  var bins=new Dictionary<int,int>();using(var sample=new Bitmap(96,96)){using(var g=Graphics.FromImage(sample)){g.Clear(Color.White);g.DrawImage(image,0,0,96,96);}for(int y=0;y<96;y++)for(int x=0;x<96;x++){var c=sample.GetPixel(x,y);int max=Math.Max(c.R,Math.Max(c.G,c.B)),min=Math.Min(c.R,Math.Min(c.G,c.B));if(max-min<25||max<45||min>225)continue;int key=((c.R/24)<<16)|((c.G/24)<<8)|(c.B/24);if(!bins.ContainsKey(key))bins[key]=0;bins[key]++;}}
  var result=new List<Color>();foreach(var item in bins.OrderByDescending(p=>p.Value)){var c=Color.FromArgb(Math.Min(255,((item.Key>>16)&255)*24+12),Math.Min(255,((item.Key>>8)&255)*24+12),Math.Min(255,(item.Key&255)*24+12));if(result.Any(v=>Math.Abs(v.R-c.R)+Math.Abs(v.G-c.G)+Math.Abs(v.B-c.B)<100))continue;result.Add(c);if(result.Count==6)break;}foreach(var c in DefaultColors){if(result.Count==6)break;if(!result.Contains(c))result.Add(c);}return result.ToArray();
 }
 void UpdateAdaptivePalette(){if(paletteSource==null)return;Color[] colors=DefaultColors;string source=paletteSource.Text;
  if(source=="Couleurs de la capture"){if(photo!=null){colors=ExtractPalette(photo);paletteInfo.Text="Couleurs dominantes de la capture, complétées si nécessaire.";}else paletteInfo.Text="Capturez ou importez une image pour extraire sa palette.";}
  else if(source=="Image de référence"){if(preferences.ReferenceColors!=null&&preferences.ReferenceColors.Length>0){colors=preferences.ReferenceColors.Take(6).Select(Color.FromArgb).ToArray();paletteInfo.Text="Palette mémorisée depuis votre image de référence.";}else paletteInfo.Text="Choisissez une image de référence ci-dessous.";}
  else paletteInfo.Text="Vos couleurs d’annotation habituelles.";
  while(colorPalette.Controls.Count>0)colorPalette.Controls[0].Dispose();foreach(var color in colors){Color value=color;var button=ModernButton(colorPalette,"","",delegate{SetColor(value);},30,false);button.BackColor=value;button.Size=new Size(30,30);tips.SetToolTip(button,"Appliquer #"+value.R.ToString("X2")+value.G.ToString("X2")+value.B.ToString("X2"));}
 }
 void InitializePersistence(string directory){dataDirectory=directory;persistenceEnabled=true;loadingPreferences=true;try{Directory.CreateDirectory(directory);string path=Path.Combine(directory,"preferences.json");if(File.Exists(path))preferences=json.Deserialize<StudioPreferences>(File.ReadAllText(path))??new StudioPreferences();ink=Color.FromArgb(preferences.Ink);captureMode.SelectedIndex=Math.Max(0,Math.Min(2,preferences.Mode));delay.Value=Math.Max(0,Math.Min(30,preferences.Delay));size.Value=Math.Max(24,Math.Min(600,preferences.Size));zoom.Value=Math.Max(1,Math.Min(8,preferences.Zoom));thickness.Value=Math.Max(1,Math.Min(18,preferences.Thickness));int index=paletteSource.Items.IndexOf(preferences.Palette);paletteSource.SelectedIndex=Math.Max(0,index);UpdateAdaptivePalette();}catch(Exception ex){status.Text="Préférences indisponibles : "+ex.Message;}finally{loadingPreferences=false;}
  captureMode.SelectedIndexChanged+=delegate{SavePreferences();};delay.ValueChanged+=delegate{SavePreferences();};size.ValueChanged+=delegate{if(!syncing)SavePreferences();};zoom.ValueChanged+=delegate{if(!syncing)SavePreferences();};thickness.ValueChanged+=delegate{if(!syncing)SavePreferences();};
  draftTimer=new Timer(){Interval=5000};draftTimer.Tick+=delegate{if(!capturing&&!dragging&&!panning&&!cropDragging&&textTarget==null)SaveDraft();};draftTimer.Start();
  Shown+=delegate{if(suppressRecovery)return;Project p=ReadDraft();if(p!=null&&MessageBox.Show(this,"Reprendre la dernière capture et ses annotations ?","Brouillon retrouvé",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){LoadDraft(p);status.Text="Brouillon restauré. Enregistrez le projet pour le conserver à l’emplacement de votre choix.";}};
  FormClosing+=delegate(object sender,FormClosingEventArgs e){if(e.Cancel)return;FinishInlineText(true);SaveDraft();SavePreferences();};FormClosed+=delegate{draftTimer.Stop();draftTimer.Dispose();};
 }
 void SavePreferences(){if(!persistenceEnabled||loadingPreferences||syncing)return;preferences.Ink=ink.ToArgb();preferences.Mode=captureMode.SelectedIndex;preferences.Delay=(int)delay.Value;preferences.Size=size.Value;preferences.Zoom=zoom.Value;preferences.Thickness=thickness.Value;preferences.Palette=paletteSource.Text;try{AtomicWrite(Path.Combine(dataDirectory,"preferences.json"),json.Serialize(preferences));}catch(Exception ex){status.Text="Préférences non enregistrées : "+ex.Message;}}
 static void AtomicWrite(string path,string text){string temp=path+".tmp";File.WriteAllText(temp,text);if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}
 Project Snapshot(){if(cachedSource==null)using(var stream=new MemoryStream()){photo.Save(stream,System.Drawing.Imaging.ImageFormat.Png);cachedSource=Convert.ToBase64String(stream.ToArray());}return new Project(){Image=cachedSource,Marks=marks,CropX=crop.X,CropY=crop.Y,CropWidth=crop.Width,CropHeight=crop.Height,Blur=blurAmount};}
 string lastDraft;void SaveDraft(){if(!persistenceEnabled||photo==null)return;try{string data=json.Serialize(Snapshot());if(data==lastDraft)return;AtomicWrite(Path.Combine(dataDirectory,"brouillon.capture"),data);lastDraft=data;}catch(Exception ex){status.Text="Brouillon non enregistré : "+ex.Message;}}
 Project ReadDraft(){foreach(string name in new string[]{"brouillon.capture","brouillon.capture.bak"})try{string path=Path.Combine(dataDirectory,name);if(!File.Exists(path))continue;var p=json.Deserialize<Project>(File.ReadAllText(path));if(p!=null&&p.Empty)return null;if(p!=null&&p.Marks!=null)using(var stream=new MemoryStream(Convert.FromBase64String(p.Image)))using(var b=new Bitmap(stream))return p;}catch{}return null;}
 void LoadDraft(Project p){using(var stream=new MemoryStream(Convert.FromBase64String(p.Image)))using(var b=new Bitmap(stream))SetPhoto(new Bitmap(b));marks=p.Marks;crop=Rectangle.Intersect(new Rectangle(p.CropX,p.CropY,Math.Max(0,p.CropWidth),Math.Max(0,p.CropHeight)),new Rectangle(Point.Empty,photo.Size));blurAmount=Math.Max(0,Math.Min(24,p.Blur));dirty=true;RefreshSelection();ResetViewport();canvas.Invalidate();}
 void BeginInlineText(Mark mark,bool isNew){FinishInlineText(true);textTarget=mark;newText=isNew;originalText=mark.Text??"";inlineText.Text=originalText;inlineText.ForeColor=Color.FromArgb(mark.Color);inlineText.Font=new Font("Segoe UI",Math.Max(10,mark.Size/5*scale),FontStyle.Bold);PositionInlineText();inlineText.Visible=true;inlineText.BringToFront();inlineText.Focus();inlineText.SelectAll();status.Text="Saisissez votre texte • Entrée : nouvelle ligne • Ctrl+Entrée : valider • Échap : annuler";}
 void PositionInlineText(){if(textTarget==null)return;UpdateViewport();int x=(int)(textTarget.X*scale+ox),y=(int)(textTarget.Y*scale+oy);inlineText.Bounds=new Rectangle(Math.Max(0,Math.Min(canvas.Width-100,x)),Math.Max(0,Math.Min(canvas.Height-70,y)),Math.Max(100,Math.Min(380,canvas.Width-Math.Max(0,x)-8)),Math.Max(70,Math.Min(150,canvas.Height-Math.Max(0,y)-8)));}
 void FinishInlineText(bool accept){if(textTarget==null||finishingText)return;finishingText=true;var mark=textTarget;string text=inlineText.Text;textTarget=null;inlineText.Visible=false;if(newText){if(!accept||String.IsNullOrWhiteSpace(text)){marks.Remove(mark);selection.Remove(mark);selected=null;}else mark.Text=text;}else if(accept&&text!=originalText&&!String.IsNullOrWhiteSpace(text)){Checkpoint();mark.Text=text;}RefreshSelection();canvas.Invalidate();finishingText=false;}
 bool HandleEditingKeys(KeyEventArgs e){if(textTarget!=null){if(e.Control&&e.KeyCode==Keys.S){FinishInlineText(true);SaveProject();e.SuppressKeyPress=true;}return true;}if(ActiveControl is TextBoxBase||ActiveControl is UpDownBase||ActiveControl is ValueSlider)return false;if(selected!=null&&!e.Control&&(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right||e.KeyCode==Keys.Up||e.KeyCode==Keys.Down)){Checkpoint();float step=e.Shift?10:1;float dx=e.KeyCode==Keys.Left?-step:e.KeyCode==Keys.Right?step:0,dy=e.KeyCode==Keys.Up?-step:e.KeyCode==Keys.Down?step:0;var group=new HashSet<Mark>(selection);group.Add(selected);foreach(var mark in group)TranslateMark(mark,dx,dy);canvas.Invalidate();e.SuppressKeyPress=true;return true;}return false;}
